import {
  type AuthoringArtifact,
  type FoldIssue,
  attach,
  requiredFieldsIssues,
  universalFoldsIssues,
} from './marketplace-tier.js';

// ─── Required-field sets (the source of the effective-required manifest) ─────

/** standardFloor — the upstream-base always-required fields (code.claude.com plugins-reference). */
export const PLUGIN_MANIFEST_BASE_REQUIRED = ['name'] as const;

/** The IS-overlay required delta (beyond the base floor). */
export const PLUGIN_MANIFEST_OVERLAY_REQUIRED = [
  'version',
  'description',
  'author',
  'homepage',
  'license',
  'keywords',
  'commands',
] as const;

/** Effective required = base ∪ overlay = the IS 8-field marketplace set (NON-NEGOTIABLE). */
export const PLUGIN_MANIFEST_REQUIRED_FIELDS = [
  ...PLUGIN_MANIFEST_BASE_REQUIRED,
  ...PLUGIN_MANIFEST_OVERLAY_REQUIRED,
] as const;

// ─── Constraint constants (mirror the JSON Schemas exactly) ──────────────────

/** IS kebab-case name surface (is-overlay — DR-062 relocated structural encoding). */
export const PLUGIN_NAME_PATTERN = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/;
/** IS name length ceiling (is-overlay — DR-062 relocated structural encoding). */
export const PLUGIN_NAME_MAX = 64;
/** Strict SemVer 2.0.0 (is-overlay — stricter than the legacy IS prefix match). */
export const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isUri(value: string): boolean {
  try {
    new URL(value);
    return true;
  } catch {
    return false;
  }
}

// ─── Layer 1: upstream base (authored by THEM) ───────────────────────────────

/**
 * The DR-062 projection-mirrored v2 base (REGENERATED from the captured
 * projection, spec_version unversioned-2026-06-12 — not a byte-copy of the
 * frozen v1 base). Required presence of upstream's standardFloor ([name] —
 * 'name is the only required field') + type/format on the FULL documented
 * surface: the metadata table ($schema, version, description, displayName,
 * author object with a required inner name, homepage/repository URIs,
 * license, keywords, defaultEnabled) + the component-path table
 * (commands/agents/skills/outputStyles string|array; hooks/mcpServers/
 * lspServers string|array|object; channels/dependencies arrays;
 * experimental {monitors, themes} each string|array; userConfig object).
 * The kebab-case name pattern + 64-char cap are NOT here — upstream
 * documents kebab-case in prose only, so the structural encoding lives in
 * the overlay (DR-062 C3, 058 #5). Length of `description` is intentionally
 * NOT capped here — the universal disclosureMarkers fold (v2: 1024) is the
 * operative cap.
 */
export function upstreamBaseIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, PLUGIN_MANIFEST_BASE_REQUIRED)];

  if ('name' in artifact && typeof artifact['name'] !== 'string') {
    issues.push({ message: 'name must be a string', path: ['name'] });
  }

  if ('$schema' in artifact && typeof artifact['$schema'] !== 'string') {
    issues.push({ message: '$schema must be a string', path: ['$schema'] });
  }

  if ('version' in artifact && typeof artifact['version'] !== 'string') {
    issues.push({ message: 'version must be a string', path: ['version'] });
  }

  if ('description' in artifact && typeof artifact['description'] !== 'string') {
    issues.push({ message: 'description must be a string', path: ['description'] });
  }

  if ('displayName' in artifact && typeof artifact['displayName'] !== 'string') {
    issues.push({ message: 'displayName must be a string', path: ['displayName'] });
  }

  if ('author' in artifact) {
    const author = artifact['author'];
    if (!isPlainObject(author)) {
      issues.push({ message: 'author must be an object', path: ['author'] });
    } else {
      for (const key of ['name'] as const) {
        if (!(key in author)) {
          issues.push({ message: `author.${key} is required`, path: ['author', key] });
        }
      }
    }
  }

  if ('homepage' in artifact) {
    const homepage = artifact['homepage'];
    if (typeof homepage !== 'string') {
      issues.push({ message: 'homepage must be a string', path: ['homepage'] });
    } else if (!isUri(homepage)) {
      issues.push({ message: 'homepage must be a valid URI', path: ['homepage'] });
    }
  }

  if ('repository' in artifact) {
    const repository = artifact['repository'];
    if (typeof repository !== 'string') {
      issues.push({ message: 'repository must be a string', path: ['repository'] });
    } else if (!isUri(repository)) {
      issues.push({ message: 'repository must be a valid URI', path: ['repository'] });
    }
  }

  if ('license' in artifact && typeof artifact['license'] !== 'string') {
    issues.push({ message: 'license must be a string', path: ['license'] });
  }

  if ('keywords' in artifact && !isStringArray(artifact['keywords'])) {
    issues.push({ message: 'keywords must be an array of strings', path: ['keywords'] });
  }

  if ('defaultEnabled' in artifact && typeof artifact['defaultEnabled'] !== 'boolean') {
    issues.push({ message: 'defaultEnabled must be a boolean', path: ['defaultEnabled'] });
  }

  if ('commands' in artifact) {
    const commands = artifact['commands'];
    if (typeof commands !== 'string' && !isStringArray(commands)) {
      issues.push({
        message: 'commands must be a string or an array of strings',
        path: ['commands'],
      });
    }
  }

  if ('agents' in artifact) {
    const agents = artifact['agents'];
    if (typeof agents !== 'string' && !isStringArray(agents)) {
      issues.push({
        message: 'agents must be a string or an array of strings',
        path: ['agents'],
      });
    }
  }

  if ('skills' in artifact) {
    const skills = artifact['skills'];
    if (typeof skills !== 'string' && !isStringArray(skills)) {
      issues.push({
        message: 'skills must be a string or an array of strings',
        path: ['skills'],
      });
    }
  }

  if ('hooks' in artifact) {
    const hooks = artifact['hooks'];
    if (typeof hooks !== 'string' && !isStringArray(hooks) && !isPlainObject(hooks)) {
      issues.push({
        message: 'hooks must be a string, an array of strings, or an object',
        path: ['hooks'],
      });
    }
  }

  if ('mcpServers' in artifact) {
    const mcpServers = artifact['mcpServers'];
    if (
      typeof mcpServers !== 'string' &&
      !isStringArray(mcpServers) &&
      !isPlainObject(mcpServers)
    ) {
      issues.push({
        message: 'mcpServers must be a string, an array of strings, or an object',
        path: ['mcpServers'],
      });
    }
  }

  if ('lspServers' in artifact) {
    const lspServers = artifact['lspServers'];
    if (
      typeof lspServers !== 'string' &&
      !isStringArray(lspServers) &&
      !isPlainObject(lspServers)
    ) {
      issues.push({
        message: 'lspServers must be a string, an array of strings, or an object',
        path: ['lspServers'],
      });
    }
  }

  if ('outputStyles' in artifact) {
    const outputStyles = artifact['outputStyles'];
    if (typeof outputStyles !== 'string' && !isStringArray(outputStyles)) {
      issues.push({
        message: 'outputStyles must be a string or an array of strings',
        path: ['outputStyles'],
      });
    }
  }

  if ('channels' in artifact && !Array.isArray(artifact['channels'])) {
    issues.push({ message: 'channels must be an array', path: ['channels'] });
  }

  if ('dependencies' in artifact && !Array.isArray(artifact['dependencies'])) {
    issues.push({ message: 'dependencies must be an array', path: ['dependencies'] });
  }

  if ('experimental' in artifact) {
    const experimental = artifact['experimental'];
    if (!isPlainObject(experimental)) {
      issues.push({ message: 'experimental must be an object', path: ['experimental'] });
    } else {
      for (const key of ['monitors', 'themes'] as const) {
        const value = experimental[key];
        if (key in experimental && typeof value !== 'string' && !isStringArray(value)) {
          issues.push({
            message: `experimental.${key} must be a string or an array of strings`,
            path: ['experimental', key],
          });
        }
      }
    }
  }

  if ('userConfig' in artifact && !isPlainObject(artifact['userConfig'])) {
    issues.push({ message: 'userConfig must be an object', path: ['userConfig'] });
  }

  return issues;
}

// ─── Layer 3: IS overlay (authored by US) ────────────────────────────────────

/**
 * The IS-only v2 delta: the seven upstream-optional metadata fields promoted
 * to IS-required (version, description, author, homepage, license, keywords,
 * commands) + the SemVer narrowing on version + the RELOCATED commands
 * array-only narrowing (DR-062 C2, 058 #2 — the v2 base carries upstream's
 * string|array union) + the RELOCATED structural name encoding (kebab
 * pattern + 64-char cap; DR-062 C3, 058 #5 — prose-only upstream) + the
 * RELOCATED optional `metadata` extension object (DR-062 C3, 058 #4). A
 * field whose type is already enforced by the base is not re-typed here —
 * its presence is the required check — to keep messages single-sourced.
 */
export function isOverlayIssues(artifact: AuthoringArtifact): FoldIssue[] {
  const issues: FoldIssue[] = [...requiredFieldsIssues(artifact, PLUGIN_MANIFEST_OVERLAY_REQUIRED)];

  if ('version' in artifact) {
    const version = artifact['version'];
    if (typeof version !== 'string') {
      issues.push({ message: 'version must be a string', path: ['version'] });
    } else if (!SEMVER_PATTERN.test(version)) {
      issues.push({ message: 'version must be strict SemVer 2.0.0', path: ['version'] });
    }
  }

  if ('commands' in artifact && !isStringArray(artifact['commands'])) {
    issues.push({ message: 'commands must be an array of strings', path: ['commands'] });
  }

  if ('name' in artifact) {
    const name = artifact['name'];
    if (typeof name !== 'string') {
      issues.push({ message: 'name must be a string', path: ['name'] });
    } else {
      if (name.length > PLUGIN_NAME_MAX) {
        issues.push({
          message: `name must be at most ${PLUGIN_NAME_MAX} characters`,
          path: ['name'],
        });
      }
      if (!PLUGIN_NAME_PATTERN.test(name)) {
        issues.push({
          message: 'name must be kebab-case (lowercase letters, digits, hyphens)',
          path: ['name'],
        });
      }
    }
  }

  if ('metadata' in artifact && !isPlainObject(artifact['metadata'])) {
    issues.push({ message: 'metadata must be an object', path: ['metadata'] });
  }

  return issues;
}

// ─── The composition (allOf of base + universal folds + overlay) ─────────────

/** Every issue from the three composed layers, in layer order. */
export function pluginManifestIssues(artifact: AuthoringArtifact): FoldIssue[] {
  return [
    ...upstreamBaseIssues(artifact),
    ...universalFoldsIssues(artifact),
    ...isOverlayIssues(artifact),
  ];
}

/** The plugin-manifest contract — pure allOf composition (base ∧ universalFolds ∧ overlay). */
export const PluginManifestSchema = attach(pluginManifestIssues);

export type PluginManifest = AuthoringArtifact;
